public int trailingZeroes(int n) {
    int count = 0;
    for (int i = 5; i <= n; i += 5) {
        int multiple = i;
        while (multiple % 5 == 0) {
            count++;
            multiple /= 5;
        }
    }
    return count;
}

code.python:
def trailingZeroes(self, n: int) -> int:
    count = 0
    for i in range(5, n + 1, 5):
        multiple = i
        while multiple % 5 == 0:
            count += 1
            multiple //= 5
    return count

